# ============================================================================
# 4b. Type-Directed Well-Typed Differential Fuzzer
# ============================================================================

WT_INT = "Int"
WT_BOOL = "Bool"


def wt_arrow(a: object, b: object) -> tuple[str, object, object]:
    return ("Fun", a, b)


def wt_type_str(t: object) -> str:
    if t == WT_INT:
        return "Int"
    if t == WT_BOOL:
        return "Bool"
    assert isinstance(t, tuple) and t[0] == "Fun"
    return f"({wt_type_str(t[1])} -> {wt_type_str(t[2])})"


def gen_wt_type(rng: random.Random, depth: int = 0) -> object:
    if depth >= 2 or rng.random() < 0.6:
        return rng.choice([WT_INT, WT_BOOL])
    return wt_arrow(gen_wt_type(rng, depth + 1), gen_wt_type(rng, depth + 1))


def env_lookup_vars_of_type(env: list[tuple[str, object]], target: object) -> list[str]:
    seen: set[str] = set()
    good: list[str] = []
    for name, ty in reversed(env):
        if name not in seen:
            seen.add(name)
            if ty == target:
                good.append(name)
    return good


def gen_wt_expr(
    rng: random.Random, env: list[tuple[str, object]], target: object, depth: int = 0
) -> str:
    # Base case when deep
    if depth >= 4:
        candidates = env_lookup_vars_of_type(env, target)
        if candidates and rng.random() < 0.7:
            return rng.choice(candidates)
        if target == WT_INT:
            return rng.choice(["0", "1", "2", "7", "(0 - 5)", "42"])
        if target == WT_BOOL:
            return rng.choice(["True", "False"])
        assert isinstance(target, tuple) and target[0] == "Fun"
        v = rng.choice(VARS)
        body = gen_wt_expr(rng, env + [(v, target[1])], target[2], depth + 1)
        return f"(/{v} -> {body})"

    # Lambda if target is arrow
    if isinstance(target, tuple) and target[0] == "Fun" and rng.random() < 0.55:
        v = rng.choice(VARS)
        body = gen_wt_expr(rng, env + [(v, target[1])], target[2], depth + 1)
        if rng.random() < 0.25:
            return f"(/{v} -> {body} : {wt_type_str(target)})"
        return f"(/{v} -> {body})"

    r = rng.random()

    # Variable of matching rightmost type
    candidates = env_lookup_vars_of_type(env, target)
    if candidates and r < 0.22:
        return rng.choice(candidates)

    # If-then-else
    if r < 0.38:
        c = gen_wt_expr(rng, env, WT_BOOL, depth + 1)
        t = gen_wt_expr(rng, env, target, depth + 1)
        e = gen_wt_expr(rng, env, target, depth + 1)
        return f"(if {c} then {t} else {e})"

    # Let (possibly sequential / shadowing!)
    if r < 0.56:
        v = rng.choice(VARS)
        vt = gen_wt_type(rng, depth + 1)
        val = gen_wt_expr(rng, env, vt, depth + 1)
        body = gen_wt_expr(rng, env + [(v, vt)], target, depth + 1)
        if rng.random() < 0.4:
            return f"(let {v} : {wt_type_str(vt)} = {val} in {body})"
        return f"(let {v} = {val} in {body})"

    # Function application (construct or pick function of type arg_t -> target)
    if r < 0.72:
        arg_t = gen_wt_type(rng, depth + 1)
        fn_t = wt_arrow(arg_t, target)
        fn_e = gen_wt_expr(rng, env, fn_t, depth + 1)
        arg_e = gen_wt_expr(rng, env, arg_t, depth + 1)
        return f"(({fn_e}) ({arg_e}))"

    # Bounded recursive function (1-arg or 2-arg curried!)
    if r < 0.84:
        fn = rng.choice(["f", "g"])
        p = rng.choice(["x", "y"])
        if rng.random() < 0.5:
            rec_t = wt_arrow(WT_INT, target)
            base_e = gen_wt_expr(rng, env + [(fn, rec_t), (p, WT_INT)], target, depth + 2)
            n_init = rng.randint(0, 4)
            return (
                f"(let rec {fn} : {wt_type_str(rec_t)} = "
                f"/{p} -> if {p} < 1 then {base_e} else {fn} ({p} - 1) "
                f"in {fn} {n_init})"
            )
        else:
            q = "z"
            rec_t = wt_arrow(WT_INT, wt_arrow(WT_INT, target))
            base_e = gen_wt_expr(
                rng, env + [(fn, rec_t), (p, WT_INT), (q, WT_INT)], target, depth + 2
            )
            n_init = rng.randint(0, 4)
            return (
                f"(let rec {fn} : {wt_type_str(rec_t)} = "
                f"/{p} -> /{q} -> if {p} < 1 then {base_e} else {fn} ({p} - 1) ({q} + {p}) "
                f"in {fn} {n_init} 1)"
            )

    # Target-specific operations
    if target == WT_INT:
        op = rng.choice(["+", "-", "*", "//", "%"])
        a = gen_wt_expr(rng, env, WT_INT, depth + 1)
        b = gen_wt_expr(rng, env, WT_INT, depth + 1)
        return f"(({a}) {op} ({b}))"
    if target == WT_BOOL:
        op = rng.choice(["==", "<"])
        a = gen_wt_expr(rng, env, WT_INT, depth + 1)
        b = gen_wt_expr(rng, env, WT_INT, depth + 1)
        return f"(({a}) {op} ({b}))"

    assert isinstance(target, tuple) and target[0] == "Fun"
    v = rng.choice(VARS)
    body = gen_wt_expr(rng, env + [(v, target[1])], target[2], depth + 1)
    return f"(/{v} -> {body})"


def test_well_typed_differential_fuzz(n_programs: int = 3000) -> dict[str, int]:
    rng = random.Random(20250302)
    counts: dict[str, int] = {}
    tested = 0
    while tested < n_programs:
        target = gen_wt_type(rng, 0)
        src = gen_wt_expr(rng, [], target, 0)
        try:
            exp = ref_run_inproc(src)
        except TimeoutError:
            continue
        assert exp != "TypeError", f"Generator produced ill-typed program!\nsrc: {src}"
        got = fast_run_inproc(src)
        assert got == exp, f"Well-typed differential mismatch!\nsrc: {src}\nref: {exp}\ngot: {got}"
        key = exp if exp in ("RuntimeError", "<function>") else "Value"
        counts[key] = counts.get(key, 0) + 1
        tested += 1
    return counts
